# Glamour Hair Salon – Windows installer script
# Paste this entire file into PowerShell and press Enter.
# It will create all project files in your Documents\Claude folder.

$dest = "C:\Users\plare\OneDrive\Documents\Claude folder\GlamourHairSalon"
New-Item -ItemType Directory -Force -Path $dest | Out-Null

$b64 = ""

$bytes = [Convert]::FromBase64String($b64)
$zipPath = "$dest\..\GlamourHairSalon.zip"
[IO.File]::WriteAllBytes($zipPath, $bytes)

Expand-Archive -Path $zipPath -DestinationPath $dest -Force
Remove-Item $zipPath

Write-Host "Done! Files extracted to: $dest" -ForegroundColor Green
